package com.on.ebx.connect.connectors;
import java.util.*;import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.node.ObjectNode;import com.on.ebx.connect.codecs.*;import com.on.ebx.connect.core.Json;import com.on.ebx.connect.spi.ConnectorException;
public final class Wave4DocumentCodecTest{
 public static void main(String[]a)throws Exception{List<JsonNode> rows=Arrays.asList(Json.object().put("id",1).put("name","Ada").put("active",true),Json.object().put("id",2).put("name","Grace").put("active",false));XlsxDocumentCodecProvider x=new XlsxDocumentCodecProvider();byte[] xb=x.serialise(rows,"xlsx",100000);ObjectNode xp=x.parse(xb,"xlsx",10,100000);check(xp.path("rows").size()==2&&"Ada".equals(xp.path("rows").get(0).path("name").asText()),"xlsx round trip");expect("max.bytes",()->x.parse(xb,"xlsx",10,xb.length-1));expect(".xlsx only",()->x.parse(xb,"xls",10,100000));
 AvroDocumentCodecProvider av=new AvroDocumentCodecProvider();byte[] ab=av.serialise(rows,"avro",100000);ObjectNode ap=av.parse(ab,"avro",10,100000);check(ap.path("rows").size()==2&&ap.path("rows").get(1).path("id").asLong()==2,"avro round trip");check("application/avro".equals(FileFormats.contentType("avro")),"service provider discovery");check(FileFormats.parse(ab,"avro",',',1,100000).path("rows").size()==1,"avro row bound");expect("flat scalar",()->av.serialise(Collections.singletonList(Json.parse("{\"nested\":{\"x\":1}}")),"avro",100000));
 expect("Apache Parquet",()->FileFormats.parse(new byte[]{1},"parquet",',',1,100));System.out.println("PASS: bounded XLSX and Avro providers; Parquet dependency gate remains explicit");}
 interface Run{void go()throws Exception;}static void expect(String s,Run r)throws Exception{try{r.go();throw new AssertionError("accepted");}catch(ConnectorException e){check(e.getMessage().contains(s),e.getMessage());}}static void check(boolean x,String m){if(!x)throw new AssertionError(m);}}
